"""Run one exact-oracle fixture pilot; never contribute it to the timing cohort."""
import argparse
import json
from pathlib import Path
import subprocess
import sys

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('fixture', choices=('early-cold-hot', 'late-cold-hot', 'hot-unique'))
    parser.add_argument('arm', choices=('ordinary', 'initial', 'always'))
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--classpath', type=Path, default=HERE / 'runtime-v1/classpath.txt')
    parser.add_argument('--warmup', type=int, default=2)
    parser.add_argument('--iterations', type=int, default=1)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted or Path(args.attempt).name != args.attempt:
        raise ValueError('A fresh simple attempt and exclusive Java slot are required')
    fixture = next(f for f in json.loads((HERE / 'fixture-oracles-v1.json').read_text())['fixtures'] if f['id'] == args.fixture)
    folder = HERE / 'qualification' / args.attempt
    command = [sys.executable, str(PHASE / 'run_java.py'), '--output', str(folder), '--classpath', str(args.classpath),
        '--main', 'org.eclipse.rdf4j.sail.lmdb.evaluation.PhaseMemoQueryHarness',
        '--property', 'rdf4j.lmdb.nativeValueMemo.enabled=' + str(args.arm != 'ordinary').lower(),
        '--property', 'rdf4j.lmdb.nativeValueMemo.retention=weak',
        '--property', 'rdf4j.lmdb.nativeValueMemo.admission=' + ('always' if args.arm == 'always' else 'initial'),
        '--property', 'rdf4j.lmdb.resultCoordinateTransport=off', '--property', 'rdf4j.lmdb.hotCounters=true',
        '--property', 'rdf4j.lmdb.queryMemory.perQueryMaxBytes=536870912', '--slot-granted', '--',
        '--arm=' + args.arm, '--source=admission-exact-pilot-v1', '--warmup=' + str(args.warmup),
        '--iterations=' + str(args.iterations), '--trace=false', '--exact-oracle=true',
        '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store'),
        *['--' + key + '=' + str(value) for key, value in fixture['arguments'].items()]]
    result = subprocess.run(command, check=False)
    if result.returncode:
        raise SystemExit(result.returncode)
    rows = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
    metadata, completion = rows[0], rows[-1]
    samples = [r for r in rows if r['type'] == 'sample']
    expected = fixture['expected']
    for name in ('querySha256', 'insertionRecipeSha256'):
        if metadata[name] != expected[name]:
            raise ValueError('Independent recipe mismatch: ' + name)
    if len(samples) != args.warmup + args.iterations or not completion['harnessReturned']:
        raise ValueError('Incomplete pilot')
    for sample in samples:
        if not sample['valid'] or not sample['orderedExactLexicalOracleValid'] or sample['timingEligible']:
            raise ValueError('Pilot oracle/route/lifecycle did not qualify')
        if sample['rows'] != expected['expectedRows'] or sample['checksum'] != expected['expectedChecksum']:
            raise ValueError('Independent result oracle differs')
    receipt = {'fixture': args.fixture, 'arm': args.arm, 'exactOracleQualified': True,
        'comparisonSample': False, 'queries': len(samples), 'independentExpected': expected,
        'sampleCounters': [r['counters'] for r in samples],
        'selections': [r['successfulSelections'] for r in samples]}
    with (folder / 'pilot-validation.json').open('x') as out:
        json.dump(receipt, out, indent=2, sort_keys=True)
        out.write('\n')
    print(json.dumps({'fixture': args.fixture, 'arm': args.arm, 'exactOracleQualified': True,
                      'queries': len(samples), 'observedLastRoute': samples[-1]['successfulSelections'],
                      'observedLastOwners': samples[-1]['memoOwners']}))


if __name__ == '__main__':
    main()
